import sys, yaml, re
data = yaml.safe_load(sys.stdin)

for scale in ['0.5B', '05B', '1.5B', '15B']:
    print(f'=== {scale} GSM8K dose-response ===')
    results = []
    for exp_id, exp in sorted(data.get('experiments', {}).items()):
        if exp.get('status') != 'DONE' or exp.get('conclusion') != 'success':
            continue
        if 'eval' not in exp_id:
            continue
        metrics = exp.get('metrics', {})
        if not metrics:
            continue
        # Match scale
        if scale in ['0.5B', '05B']:
            if '05B' not in exp_id and '0.5B' not in exp_id:
                continue
        elif scale in ['1.5B', '15B']:
            if '15B' not in exp_id and '1.5B' not in exp_id:
                continue
            if '05B' in exp_id:  # skip 0.5B
                continue

        # Extract GSM8K metric
        gsm = None
        for k, v in metrics.items():
            if 'gsm8k' in k.lower() and 'para' not in k.lower():
                if isinstance(v, dict):
                    gsm = v.get('exact_match', v.get('accuracy'))
                else:
                    gsm = v
                break

        if gsm is not None:
            # Extract dosage
            dose_match = re.search(r'd(\d+)', exp_id)
            dose = int(dose_match.group(1)) if dose_match else -1
            seed_match = re.search(r's(\d+)', exp_id)
            seed = seed_match.group(1) if seed_match else '?'
            # Check if aligned (not para)
            is_para = 'para' in exp_id
            if not is_para:
                results.append((dose, seed, gsm, exp_id))

    results.sort()
    for dose, seed, gsm, eid in results:
        pct = gsm * 100 if gsm <= 1 else gsm
        print(f'  d{dose:03d} s{seed}: {pct:.1f}%  ({eid})')
    print()
